package br.edu.exemplo.ia.project.internal; import br.edu.exemplo.ia.project.api.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ProjectService implements ProjectFacade { private final ProjectRepository repo; public ProjectService(ProjectRepository repo){this.repo=repo;} public ProjectView create(CreateProjectCommand c){return map(repo.save(new AIProject(new ProjectName(c.name()),c.area())));} public List<ProjectView> list(){return repo.findAll().stream().map(this::map).toList();} public boolean exists(UUID id){return repo.existsById(id);} private ProjectView map(AIProject p){return new ProjectView(p.getId(),p.getName().value(),p.getArea());} }
